<script setup>
import {computed} from 'vue'
import {useI18n} from 'vue-i18n'
import WeatherIcon from './WeatherIcon.vue'
import {ringRemaining} from './calendar.js'
import {remaining,windowLabel,compactReset,stamp,isStale} from './format.js'
import {weatherKind,weatherMetric} from './weather.js'
import {observationExpired} from './system-format.js'
const props=defineProps(['data','clock','connected','busy','mode','error','motion','visible','pollStarted','kiosk'])
defineEmits(['manage','display','exit','motion'])
const {t,locale}=useI18n()
const provider=computed(()=>props.data?.providers?.find(p=>p.provider==='codex'))
const windows=computed(()=>provider.value?.windows?.slice(0,2)||[])
const weather=computed(()=>props.data?.observations?.find(o=>o.provider==='weather'))
const state=computed(()=>!props.connected?'status.cached':provider.value&&isStale(provider.value,props.data,props.clock)?'status.stale':provider.value?.status==='ok'?'status.fresh':'status.unavailable')
const temp=computed(()=>weather.value?.status==='ok'?weatherMetric(weather.value,'temperature'):null)
const kind=computed(()=>weatherKind(weather.value?.status==='ok'?weatherMetric(weather.value,'code'):null))
const cycleDelay=computed(()=>{void props.visible;return -Math.max(0,(Date.now()-props.pollStarted)/1000)%30+'s'})
const percent=w=>remaining(w?.used_percent,locale.value,t('widget.unknown'))
const date=v=>stamp(v,locale.value,t('widget.notCollected'))
</script>
<template><section class="orbit-screen" :class="{'orbit-moving':motion&&visible}" :style="{'--cycle-delay':cycleDelay}" data-orbit>
<header class="orbit-header"><div class="brand-lockup"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7V3h7M14 3h7v7M21 14v7h-7M10 21H3v-7M8 8h8v8H8z"/></svg><span>Pixora</span></div><div class="orbit-today"><span>{{clock.toLocaleDateString(locale,{month:'long',day:'numeric',weekday:'short'})}}</span><span v-if="weather" class="orbit-weather"><WeatherIcon :kind="kind"/>{{weather.entries?.[0]?.title||weather.entity_id}} {{temp===null?t('widget.unknown'):Math.round(temp)+'°'}} {{t('weather.'+kind)}} <small v-if="!connected||observationExpired(weather,clock)||weather.status!=='ok'">{{t(!connected?'status.cached':weather.status!=='ok'?'status.unavailable':'status.stale')}}</small></span><span v-else>{{t('orbit.weather')}} · {{t('widget.notCollected')}}</span></div></header>
<div class="orbit-canvas"><div class="orbit-clock"><span>YOUR DAILY ORBIT</span><time>{{clock.toLocaleTimeString(locale,{hour:'2-digit',minute:'2-digit',hour12:false})}}</time><p>{{t('orbit.presence')}}</p></div>
<div class="orbit-graphic"><div class="orbit-halo"/><svg viewBox="0 0 400 400" role="img" :aria-label="'Codex '+windows.map(w=>windowLabel(w.duration_minutes,t,locale)+' '+percent(w)).join('; ')"><g v-for="i in [0,1]" :key="i" :class="'orbit-ring-'+i"><circle class="orbit-track" cx="200" cy="200" :r="164-i*22"/><circle v-if="ringRemaining(windows[i]?.used_percent)!==null" class="orbit-value" cx="200" cy="200" :r="164-i*22" pathLength="100" stroke-dasharray="100" :stroke-dashoffset="100-ringRemaining(windows[i]?.used_percent)" transform="rotate(-90 200 200)"/></g></svg><div v-if="connected&&!error&&provider" class="orbit-satellite" :title="t('orbit.rhythm')"><i/></div><div class="orbit-center"><span>CODEX · {{windowLabel(windows[0]?.duration_minutes,t,locale)}}</span><strong>{{percent(windows[0])}}</strong><span>{{t('widget.remaining')}}</span></div></div>
<div class="orbit-legends"><div v-for="(w,i) in windows" :key="w.name" :class="'orbit-ring-'+i"><h2>● {{windowLabel(w.duration_minutes,t,locale)}}</h2><strong>{{percent(w)}}</strong><p>{{t('widget.reset',{time:compactReset(w.resets_at,locale,t('widget.unknownTime'))})}}</p></div><p v-if="!windows.length">{{t('orbit.noQuota')}}</p></div></div>
<div class="orbit-bottom"><div class="orbit-status" role="status"><span v-if="mode==='demo'" class="orbit-warning">{{t('data.demo')}} · </span><span>{{t(connected?'status.connected':'status.offline')}} · {{t(state)}}</span><span v-if="busy"> · {{t('ui.refreshing')}}</span><p v-if="error" role="alert" class="orbit-warning">{{t(error.key,error.params||{})}}</p><details><summary>{{t('orbit.source')}}</summary><p>{{t('orbit.rhythm')}}</p><p v-if="provider">{{provider.source}} · {{date(provider.observed_at)}}</p><p>{{t('status.sync',{time:date(data?.server_time)})}}</p><p v-if="weather">{{t('orbit.weather')}} · {{date(weather.collected_at)}} · <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a></p></details></div><nav class="orbit-controls" :aria-label="t('ui.settings')"><button @click="$emit('motion')" :aria-pressed="motion">{{t('orbit.motion')}} {{motion?'●':'○'}}</button><button @click="$emit('manage')">{{t('orbit.manage')}}</button><button @click="$emit(kiosk?'exit':'display')">{{t(kiosk?'config.exit':'config.display')}}</button></nav></div>
</section></template>
<style scoped>
.orbit-screen{--ground:#080f11;--ink:#eaf2ee;--muted:#99aaa5;--accent:#8ee5bf;background:var(--ground);color:var(--ink);min-height:100vh;min-height:100dvh;display:flex;flex-direction:column;padding:max(22px,env(safe-area-inset-top)) max(28px,env(safe-area-inset-right)) max(18px,env(safe-area-inset-bottom)) max(28px,env(safe-area-inset-left));gap:16px;font-size:12px}.orbit-header{display:flex;align-items:center;justify-content:space-between;gap:16px}.orbit-today{min-width:0;display:flex;gap:20px;align-items:center;color:var(--muted)}.orbit-weather{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;gap:6px;overflow-wrap:anywhere}.orbit-weather :deep(svg){width:24px;height:24px;fill:none;stroke:var(--accent);stroke-width:2}.orbit-canvas{flex:1;display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.5fr) minmax(0,1fr);gap:24px;align-items:center;max-width:1300px;width:100%;margin:auto}.orbit-clock>span{font-size:10px;color:var(--muted)}.orbit-clock time{display:block;font-size:clamp(32px,5vw,64px);font-weight:300;letter-spacing:-2px;margin:12px 0;white-space:nowrap}.orbit-clock p{color:var(--muted)}.orbit-graphic{position:relative;width:100%;max-width:440px;aspect-ratio:1;justify-self:center}.orbit-graphic>svg{width:100%;height:100%;display:block;overflow:visible}.orbit-track,.orbit-value{fill:none;stroke-width:9;stroke-linecap:round}.orbit-track{stroke:#213330}.orbit-ring-0{color:#8ee5bf}.orbit-ring-1{color:#8ebcdd}.orbit-value{stroke:currentColor}.orbit-moving .orbit-value{transition:stroke-dashoffset 1.2s ease}.orbit-center{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;color:var(--muted);font-size:clamp(10px,1.2vw,14px)}.orbit-center strong{font-size:clamp(46px,7vw,96px);font-weight:300;color:var(--ink);letter-spacing:-3px}.orbit-legends{display:flex;flex-direction:column;gap:28px}.orbit-legends h2{font-size:13px;font-weight:400;color:inherit}.orbit-legends strong{display:block;font-size:clamp(28px,4vw,48px);font-weight:300;margin:6px 0}.orbit-legends p{font-size:12px;color:var(--muted);line-height:1.6;overflow-wrap:anywhere}.orbit-bottom{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;color:var(--muted);font-size:11px}.orbit-status{line-height:1.7;min-width:0}.orbit-status details{margin-top:4px}.orbit-status summary{cursor:pointer;min-height:24px}.orbit-status a{color:inherit}.orbit-warning{color:#e7c78d}.orbit-controls{display:flex;flex-wrap:wrap;gap:4px;justify-content:flex-end}.orbit-controls button{background:transparent;color:var(--muted);border:0;min-height:44px;font-size:11px;padding:8px}.orbit-controls button:hover,.orbit-controls button:focus-visible{color:var(--ink);background:#213330}.orbit-halo{position:absolute;inset:3%;border:1px solid #213330;border-radius:50%;opacity:.4;pointer-events:none}.orbit-moving .orbit-halo{animation:orbit-breathe 6s ease-in-out infinite}.orbit-satellite{position:absolute;inset:3.25%;border-radius:50%;pointer-events:none}.orbit-satellite i{position:absolute;width:4px;height:4px;background:#c9dbd3;border-radius:50%;top:-2px;left:calc(50% - 2px)}.orbit-moving .orbit-satellite{animation:orbit-cycle 30s linear infinite;animation-delay:var(--cycle-delay)}@keyframes orbit-cycle{to{transform:rotate(360deg)}}@keyframes orbit-breathe{50%{opacity:.8}}
@media(orientation:portrait),(max-width:600px) and (min-height:600px){.orbit-screen{padding-left:max(22px,env(safe-area-inset-left));padding-right:max(22px,env(safe-area-inset-right))}.orbit-today{flex:1;flex-direction:column;gap:4px;align-items:flex-end;font-size:11px}.orbit-canvas{grid-template-columns:minmax(0,1fr);gap:16px;padding:20px 0}.orbit-clock{text-align:center}.orbit-clock time{font-size:42px;margin:8px 0}.orbit-clock p{display:none}.orbit-graphic{width:min(100%,36vh,340px)}.orbit-center strong{font-size:64px}.orbit-legends{flex-direction:row;justify-content:space-between;gap:20px}.orbit-legends>div{flex:1;min-width:0}.orbit-legends strong{font-size:36px}.orbit-bottom{flex-direction:column;align-items:stretch}.orbit-controls{justify-content:flex-start}}
@media(orientation:landscape) and (max-height:600px){.orbit-screen{gap:8px;padding-top:max(12px,env(safe-area-inset-top));padding-bottom:max(8px,env(safe-area-inset-bottom))}.orbit-graphic{width:min(100%,64vh)}.orbit-center strong{font-size:clamp(40px,7vw,72px)}.orbit-legends{gap:16px}.orbit-legends strong{font-size:32px}.orbit-header{font-size:11px}}
@media(prefers-reduced-motion:reduce){.orbit-screen *{animation:none!important;transition:none!important}}
</style>
